/*!
 * Minimal local Rellax-compatible helper for TechCourse.
 * Keeps existing .rellax flow working without external CDN loading.
 */
(function(window, document) {
    'use strict';

    function clamp(value, min, max) {
        return Math.min(Math.max(value, min), max);
    }

    function Rellax(selector, options) {
        this.selector = selector;
        this.options = options || {};
        this.elements = Array.prototype.slice.call(document.querySelectorAll(selector));
        this.handleScroll = this.handleScroll.bind(this);
        this.handleResize = this.handleResize.bind(this);

        if (!this.elements.length) {
            return;
        }

        this.handleResize();
        window.addEventListener('scroll', this.handleScroll, { passive: true });
        window.addEventListener('resize', this.handleResize, { passive: true });
        this.handleScroll();
    }

    Rellax.prototype.handleResize = function() {
        this.viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
        this.handleScroll();
    };

    Rellax.prototype.handleScroll = function() {
        var viewportCenter = this.viewportHeight / 2;

        this.elements.forEach(function(element) {
            var rect = element.getBoundingClientRect();
            var speed = parseFloat(element.getAttribute('data-rellax-speed') || 0);
            var distanceFromCenter = rect.top + (rect.height / 2) - viewportCenter;
            var translateY = clamp(distanceFromCenter * (speed * -0.08), -36, 36);

            element.style.transform = 'translate3d(0, ' + translateY.toFixed(2) + 'px, 0)';
        });
    };

    Rellax.prototype.destroy = function() {
        window.removeEventListener('scroll', this.handleScroll);
        window.removeEventListener('resize', this.handleResize);

        this.elements.forEach(function(element) {
            element.style.transform = '';
        });
    };

    window.Rellax = Rellax;
})(window, document);
